parameters.text:
=Check if the following buyer lead already exists in the CRM database.

Buyer Information:

Name: {{$json.name}}

Location: {{$json.location}}

Property Type: {{$json.property}}

Budget: {{$json.budget}}

Email: {{$json.email}}

Use the connected Google Sheet tool to read existing records and determine if this lead already exists.

Return the result in the required JSON format.

parameters.jsCode:
let raw = $json;

// If AI returned string instead of JSON
if (typeof raw === "string") {
  try {
    raw = JSON.parse(raw);
  } catch (e) {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      raw = JSON.parse(match[0]);
    } else {
      raw = {};
    }
  }
}

// Helper functions
const clean = (val, fallback = "") => {
  if (val === undefined || val === null) return fallback;
  return String(val).trim();
};

const normalizeStatus = (status) => {
  const s = clean(status).toLowerCase();

  if (s.includes("duplicate")) return "duplicate";
  if (s.includes("possible")) return "possible_duplicate";
  if (s.includes("new")) return "new_lead";

  return "unknown";
};

const normalizeAction = (action) => {
  const a = clean(action).toLowerCase();

  if (a.includes("skip")) return "skip_record";
  if (a.includes("review")) return "review_required";
  if (a.includes("create")) return "create_new_record";

  return "review_required";
};

// Extract matched record safely
const record = raw.matched_record || {};

const normalized = {
  lead_status: normalizeStatus(raw.lead_status),

  action: normalizeAction(raw.action),

  reason: clean(raw.reason),

  matched_record: {
    name: clean(record.name),
    email: clean(record.email),
    location: clean(record.location),
    property_type: clean(record.property_type),
    budget: clean(record.budget)
  }
};

// Add helper flags for workflow logic
normalized.is_duplicate = normalized.lead_status === "duplicate";
normalized.is_possible_duplicate =
  normalized.lead_status === "possible_duplicate";
normalized.is_new_lead = normalized.lead_status === "new_lead";

return [{ json: normalized }];

parameters.text:
=Buyer Requirements:

Name: {{ $json.buyer_name }}
Location Preference: {{ $json.location }}
Budget: {{ $json.budget }}
Property Type: {{ $json.property_type }}
Bedrooms: {{ $json.bedrooms }}
Additional Requirements: {{ $json.additional_requirements }}

Property Database:

{{ $json.properties }}

Instructions:
Compare the buyer requirements with the property database and return matching properties using the required JSON format.

parameters.jsCode:
// Get AI output from previous node
let rawOutput = $json.output || $json.response || $json.text || "";

// Remove markdown formatting if AI returned ```json
if (typeof rawOutput === "string") {
	rawOutput = rawOutput
		.replace(/```json/g, "")
		.replace(/```/g, "")
		.trim();
}

// Parse JSON safely
let parsed;

try {
	parsed = typeof rawOutput === "string" ? JSON.parse(rawOutput) : rawOutput;
} catch (error) {
	return [
		{
			json: {
				status: "error",
				message: "Unable to parse AI output",
				raw_output: rawOutput
			}
		}
	];
}

// If no property match
if (!parsed.match_found) {
	return [
		{
			json: {
				match_found: false,
				total_matches: 0,
				message: parsed.message || "No matching properties found"
			}
		}
	];
}

// Normalize matched properties
const properties = parsed.matched_properties || [];

const normalized = properties.map(property => {
	return {
		json: {
			match_found: parsed.match_found,
			total_matches: parsed.total_matches || properties.length,
			property_id: property.property_id || "",
			property_name: property.property_name || "",
			location: property.location || "",
			price: property.price || "",
			bedrooms: property.bedrooms || "",
			property_type: property.property_type || "",
			match_score: property.match_score || 0
		}
	};
});

return normalized;

